    Field algorithmField = InternalFileDecryptor.class.getDeclaredField("algorithm");
    algorithmField.setAccessible(true);
    algorithmField.set(decryptor, algorithm);

    Field processedField =
        InternalFileDecryptor.class.getDeclaredField("fileCryptoMetaDataProcessed");
    processedField.setAccessible(true);
    processedField.setBoolean(decryptor, true);
